function startNight(){if(state.phase!=='day'||state.gameOver)return;state.phase='night';state.spawned=0;state.total=5+state.day*2;state.spawnTimer=.45;state.enemies=[];state.shots=[];tuneLighting(true);refresh();document.querySelectorAll('.tool').forEach(b=>b.classList.toggle('active',b.dataset.tool==='build'));state.tool='build';ui.hint.textContent='Tap a glowing pad to build a guard tower (5 coins).';toast(`Night ${state.day}: ${state.total} creatures on the trail!`)}
