function actOnPlot(plot){if(state.phase!=='day'){toast('It is too dark to tend the garden!');return}if(state.tool==='plant'){if(plot.plant){toast('That bed already has a crop.');return}if(!state.seeds){toast('No seeds! Tap the seed counter to buy some.');return}state.seeds--;plot.plant={stage:0};plot.watered=false;drawPlant(plot);toast('Seed planted. Give it a drink!')}else if(state.tool==='water'){if(!plot.plant){toast('Plant a seed here first.');return}if(plot.plant.stage>=2){toast('This crop is ripe and ready to harvest!');return}if(plot.watered){toast('Already watered today.');return}plot.watered=true;drawPlant(plot);toast('Lovely! Your crop will grow overnight.')}else if(state.tool==='harvest'){if(!plot.plant||plot.plant.stage<2){toast('Not ripe yet — water it and sleep a couple of nights.');return}const payout=4+Math.floor(Math.random()*3);state.coins+=payout;state.seeds+=Math.random()<.45?1:0;plot.plant=null;plot.watered=false;drawPlant(plot);refresh();toast(`Harvest sold for ${payout} coins!`)}else toast('Use a garden bed for crops. Build on a glowing pad.')}
function actOnPad(pad){if(!pad)return;if(state.phase==='day'){toast('Guards will be needed after sunset.');return}if(pad.tower){toast('This pad already has a guard tower.');return}if(state.coins<5){toast('Need 5 coins for a guard tower. Harvest crops first!');return}state.coins-=5;placeTower(pad);refresh();toast('Guard tower built! It fires at nearby creatures.')}
