function advanceNight(dt){if(state.spawned<state.total){state.spawnTimer-=dt;if(state.spawnTimer<=0){const e=createEnemy();e.group.position.set(pathPts[0][0],0,pathPts[0][1]);state.enemies.push(e);state.spawned++;state.spawnTimer=Math.max(.65,1.35-state.day*.035)}}for(const pad of pads){if(!pad.tower)continue;const t=pad.tower;t.cooldown-=dt;if(t.cooldown<=0){let target=null,best=t.range;for(const e of state.enemies){if(e.hp<=0)continue;const d=e.group.position.distanceTo(pad.group.position);if(d<best){best=d;target=e}}if(target){const from=pad.group.position.clone();from.y=1.1;addShot(from,target);t.cooldown=.82}}}for(let i=state.enemies.length-1;i>=0;i--){const e=state.enemies[i];if(e.hit>0){e.hit-=dt;e.group.scale.setScalar(e.hit>.12?1.12:1)}e.progress+=e.speed*dt;let remaining=e.progress,idx=0;while(idx<pathPts.length-1){const a=new THREE.Vector3(pathPts[idx][0],0,pathPts[idx][1]),b=new THREE.Vector3(pathPts[idx+1][0],0,pathPts[idx+1][1]),len=a.distanceTo(b);if(remaining<=len){const f=remaining/len;e.group.position.lerpVectors(a,b,f);e.group.position.y=Math.abs(Math.sin(e.progress*9))*.12;e.group.rotation.y=-Math.atan2(b.z-a.z,b.x-a.x);break}remaining-=len;idx++}for(const leg of e.legs)leg.rotation.x=Math.sin(e.progress*13)*.45;if(idx>=pathPts.length-1){state.health=Math.max(0,state.health-1);scene.remove(e.group);state.enemies.splice(i,1);refresh();toast('A creature reached the farmhouse!');if(!state.health){showEnd(false);return}}}for(let i=state.shots.length-1;i>=0;i--){const s=state.shots[i];if(!s.target.group.parent||s.target.hp<=0){scene.remove(s.mesh);state.shots.splice(i,1);continue}const destination=s.target.group.position.clone();destination.y+=.55;const dir=destination.sub(s.mesh.position);const distance=dir.length();if(distance<.32){s.target.hp-=s.damage;s.target.hit=.18;scene.remove(s.mesh);state.shots.splice(i,1);if(s.target.hp<=0){scene.remove(s.target.group);const ix=state.enemies.indexOf(s.target);if(ix>=0)state.enemies.splice(ix,1);state.coins+=1;if(Math.random()<.35)state.wood++;refresh();}}else s.mesh.position.add(dir.normalize().multiplyScalar(Math.min(distance,s.speed*dt)))}if(state.spawned===state.total&&state.enemies.length===0){startDay()}}
