+=1;if(Math.random()<.35)state.wood++;refresh();}}else s.mesh.position.add(dir.normalize().multiplyScalar(Math.min(distance,s.speed*dt)))}if(state.spawned===state.total&&state.enemies.length===0){startDay()}}
